package com.classvoice.controller; import com.classvoice.dao.LectureDAO; import com.classvoice.model.User; import com.classvoice.util.WebUtil; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/teacher/lecture/activate") public class ActivateLectureServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");long id=WebUtil.longParam(r,"lectureId");new LectureDAO().setStatus(id,u.getUserId(),"active");p.sendRedirect(r.getContextPath()+"/teacher/topics?lectureId="+id);}catch(Exception e){throw new ServletException(e);}}}
